import React from 'react';
import { useHistory } from 'react-router-dom';

const SplashScreen = () => {
  const history = useHistory();

  const goToPlaceSelection = () => {
    history.push('/place-selection'); // 장소 선택 화면으로 이동
  };

  return (
    <div>
      <h1>꾸미는 장소를 만들러 가볼까요?</h1>
      <img src="/static/splash-image.png" alt="Splash" />
      <button onClick={goToPlaceSelection}>Next</button>
    </div>
  );
};

export default SplashScreen;
